 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            # Five-cell cap, two vertical sides around the marker, and a
            # full-width baseline two rows below it.
            for dc in range(-2, 3):
                rr, cc = r - 2, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 5
            for dr in (-1, 0, 1):
                rr = r + dr
                for dc in (-2, 2):
                    cc = c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 2
            # The cap's center is also marked 5 on the row above the 3.
            if 0 <= r - 1 < h and 0 <= c < w:
                out[r - 1][c] = 5
            rr = r + 2
            if 0 <= rr < h:
                for cc in range(w):
                    out[rr][cc] = 8 if c - 2 <= cc <= c + 2 else 2
    return out
